const messaging = firebase.messaging();

// Handle background messages
messaging.onBackgroundMessage((payload) => {
  console.log(
    "[firebase-messaging-sw.js] Received background message ",
    payload,
  );

  const title =
    payload.notification?.title || payload.data?.title || "Tribe Green Admin";
  const body =
    payload.notification?.body ||
    payload.data?.body ||
    "You have a new enquiry.";

  const notificationOptions = {
    body: body,
    icon: payload.notification?.icon || "icons/Icon-192.png",
    badge: "icons/Icon-192.png",
    tag:
      payload.notification?.tag || payload.data?.tag || "tribe-green-enquiries",
    data: {
      ...payload.data,
      link: payload.fcmOptions?.link || payload.data?.link || "/#/dashboard",
    },
  };

  return self.registration.showNotification(title, notificationOptions);
});

// Handle notification click to navigate/focus
self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const targetUrl = new URL(
    event.notification.data?.link || "/#/dashboard",
    self.location.origin,
  ).href;

  event.waitUntil(
    clients
      .matchAll({
        type: "window",
        includeUncontrolled: true,
      })
      .then(async (windowClients) => {
        for (const client of windowClients) {
          if (client.url.startsWith(self.location.origin)) {
            await client.navigate(targetUrl);
            return client.focus();
          }
        }

        return clients.openWindow(targetUrl);
      }),
  );
});
